pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testRegression_property() public {
        vm.prank(address(1));
        bool ok;
        try c.assertionDisputedCallback(bytes32(uint256(42))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference should revert when caller is not optimistic asserter");
    }
}
